class Solution:
    def levelOrder(self, root) -> list[list[int]]:
        if not root:
            return []
        from collections import deque
        result = []
        queue = deque([root])
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.popleft()
                level.append(node.val)
                for child in node.children:
                    queue.append(child)
            result.append(level)
        return result

